import * as crypto from 'crypto';

/**
 * Secret API keys are stored as a SHA-256 hash, so a database dump or an
 * error log cannot leak a usable credential. The plaintext is returned to the
 * merchant exactly once, at generation time.
 *
 * A plain hash (rather than bcrypt) is deliberate here: the key is 128 bits of
 * entropy generated by the server, so it is not brute-forceable from the hash,
 * and every API request needs an indexed lookup rather than a per-row compare.
 */
export class ApiKeyUtil {
  /** Hex-encoded SHA-256 of the key, used as the indexed lookup value. */
  static hash(apiKey: string): string {
    return crypto.createHash('sha256').update(apiKey, 'utf8').digest('hex');
  }

  /** Last 4 characters, so a merchant can identify a key they cannot see. */
  static hint(apiKey: string): string {
    return apiKey.slice(-4);
  }

  /** A new secret key, in the `ora_sk_live_<32 hex>` format. */
  static generateSecretKey(): string {
    return `ora_sk_live_${crypto.randomBytes(16).toString('hex')}`;
  }
}
